  const allCoupons = allBusinesses
    .filter(b => b.deals && b.deals.length > 0)
    .slice(0, 200)
    .map((b, i) => ({
      id: 'cp' + String(i + 1).padStart(3, '0'),
      category: b.category,
      icon: b.category === 'food' ? '🍜' : b.category === 'coffee' ? '☕' : b.category === 'hotel' ? '🏨' : '🎬',
      name: b.deals[0].desc,
      desc: b.name.replace(/（.+）/, ''),
      price: String(b.deals[0].price),
      origPrice: String(b.deals[0].orig),
      discount: (Math.round(b.deals[0].price / b.deals[0].orig * 100) / 10).toFixed(1) + '折',
      distance: b.distance,
      shop: b.name.replace(/（.+）/, ''),
      sold: b.deals[0].sold,
    }));

  return {
    all: allBusinesses,
    coupons: allCoupons,
    totalCount: allBusinesses.length,
    getAll: function() { return allBusinesses; },
    getByCategory: function(cat) { return allBusinesses.filter(function(b) { return b.category === cat; }); },
    getFood: function() { return allBusinesses.filter(function(b) { return b.category === 'food'; }); },
    getCoffee: function() { return allBusinesses.filter(function(b) { return b.category === 'coffee'; }); },
    getAttractions: function() { return allBusinesses.filter(function(b) { return b.category === 'ticket'; }); },
    getHotels: function() { return allBusinesses.filter(function(b) { return b.category === 'hotel'; }); },
    getShopping: function() { return []; },
    getEntertainment: function() { return []; },
    getCoupons: function() { return allCoupons; },
    getTotalCount: function() { return allBusinesses.length; },
  };
